<?php
$fullName=$application['applicant_name'];
$lifecycle=[
    ['key'=>'intake','label'=>'Intake','statuses'=>['draft','submitted','resubmitted'],'href'=>'#overview'],
    ['key'=>'review','label'=>'Review','statuses'=>['eligibility_check','under_review'],'href'=>'#academic'],
    ['key'=>'corrections','label'=>'Corrections','statuses'=>['correction_required'],'href'=>'#decision'],
    ['key'=>'approved','label'=>'Approved','statuses'=>['approved'],'href'=>'#decision'],
    ['key'=>'selected','label'=>'Selected','statuses'=>['selected'],'href'=>'#decision'],
    ['key'=>'payment','label'=>'Payment','statuses'=>['payment_pending'],'href'=>'#payments'],
    ['key'=>'verified','label'=>'Fee verified','statuses'=>['fee_verified'],'href'=>'#payments'],
    ['key'=>'admitted','label'=>'Admitted','statuses'=>['admitted'],'href'=>'#timeline'],
    ['key'=>'closed','label'=>'Closed','statuses'=>['rejected','withdrawn'],'href'=>'#timeline'],
];
$currentStage=0;
foreach($lifecycle as $index=>$stage)if(in_array($application['status'],$stage['statuses'],true)){$currentStage=$index;break;}
$completedThrough=$currentStage-1;
if(in_array($application['status'],['rejected','withdrawn'],true)&&$timeline){$originStatus=(string)($timeline[0]['from_status']??'');foreach($lifecycle as $index=>$stage)if(in_array($originStatus,$stage['statuses'],true)){$completedThrough=$index;break;}}
$verifiedDocuments=count(array_filter($documents,static fn(array $document):bool=>$document['status']==='verified'));
$verifiedPayment=(bool)array_filter($payments,static fn(array $payment):bool=>$payment['status']==='verified');
$openCorrections=count(array_filter($corrections,static fn(array $correction):bool=>$correction['status']==='open'));
$reviewSignals=[
    ['label'=>'Reviewer','value'=>$application['assigned_to']?'Assigned':'Unassigned','ready'=>(bool)$application['assigned_to'],'href'=>'#decision'],
    ['label'=>'Eligibility','value'=>ucwords(str_replace('_',' ',$application['eligibility_status'])),'ready'=>$application['eligibility_status']==='eligible','href'=>'#academic'],
    ['label'=>'Documents','value'=>$verifiedDocuments.'/'.count($documents).' verified','ready'=>count($documents)>0&&$verifiedDocuments===count($documents),'href'=>'#documents'],
    ['label'=>'Corrections','value'=>$openCorrections?$openCorrections.' open':'None open','ready'=>$openCorrections===0,'href'=>'#decision'],
    ['label'=>'Payment','value'=>$verifiedPayment?'Verified':($payments?'Pending review':'Not recorded'),'ready'=>$verifiedPayment,'href'=>'#payments'],
    ['label'=>'Allocation','value'=>$allocation?($allocation['program_name'].' · '.$allocation['status']):'Not allocated','ready'=>(bool)$allocation,'href'=>'#decision'],
];
$nextAction=match($application['status']){
    'submitted','resubmitted'=>'Run eligibility checks, then begin review.',
    'eligibility_check'=>'Resolve eligibility flags and review evidence.',
    'under_review'=>'Verify documents, then approve, select, or request a targeted correction.',
    'correction_required'=>'Track the targeted correction response before resuming review.',
    'approved'=>'Review programme eligibility and seat availability before selection.',
    'selected','payment_pending'=>'Review admission-fee evidence.',
    'fee_verified'=>'Confirm allocation and complete admission.',
    'admitted'=>'Admission is complete; retain the audit trail.',
    'rejected','withdrawn'=>'This record is closed. Review the timeline for the decision reason.',
    default=>'Complete the application intake review.',
};
?>
<div class="record-header"><div><a class="back-link" href="<?= url('admin/applications') ?>">← All applications</a><div class="record-title"><span class="record-avatar"><?= e(strtoupper(substr($fullName,0,1))) ?></span><div><span class="eyebrow"><?= e($application['application_number']?:'Draft application') ?></span><h1><?= e($fullName) ?></h1><p><?= e($application['email']) ?> · <?= e($application['mobile']) ?> · <?= e($application['cycle_name']) ?></p></div></div></div><div class="record-actions"><span class="status-pill status-<?= e($application['status']) ?> large"><?= e(ucwords(str_replace('_',' ',$application['status']))) ?></span><a class="button button-outline" target="_blank" href="<?= url('admin/applications/'.$application['id'].'/generated/application') ?>">▣ Print summary</a><details class="document-menu"><summary class="button button-outline">Letters ▾</summary><div><?php foreach(['cover-sheet'=>'Cover sheet','acknowledgement'=>'Acknowledgement','correction-memo'=>'Correction memo','offer-letter'=>'Offer letter','admission-letter'=>'Admission confirmation'] as $kind=>$label):?><a target="_blank" href="<?= url('admin/applications/'.$application['id'].'/generated/'.$kind) ?>"><?= e($label) ?></a><?php endforeach?></div></details></div></div>
<div class="record-meta"><div><span>Submitted</span><b><?= format_date($application['submitted_at'],true) ?></b></div><div><span>Completion</span><b><?= e($application['completion_percentage']) ?>%</b></div><div><span>Eligibility</span><b><?= e(ucwords(str_replace('_',' ',$application['eligibility_status']))) ?></b></div><div><span>Assigned reviewer</span><b><?= e($application['assigned_reviewer_name']?:'Unassigned') ?></b></div></div>
<section class="application-lifecycle" aria-labelledby="lifecycle-title"><div class="lifecycle-heading"><div><span class="eyebrow">Graphical workflow</span><h2 id="lifecycle-title">Application lifecycle</h2></div><a href="<?= url('admin/applications?view=board') ?>">Return to pipeline →</a></div><ol><?php foreach($lifecycle as $index=>$stage):$stageState=$index===$currentStage?'current':($index<=$completedThrough?'complete':'future');?><li class="<?= e($stageState) ?>"><a href="<?= e($stage['href']) ?>" <?= $stageState==='current'?'aria-current="step"':'' ?>><i><?= $stageState==='complete'?'✓':$index+1 ?></i><span><?= e($stage['label']) ?></span></a></li><?php endforeach ?></ol></section>
<section class="guided-review-summary" aria-labelledby="guided-review-title"><div class="guided-review-intro"><span class="eyebrow">Guided review</span><h2 id="guided-review-title">Decision readiness</h2><p><?= e($nextAction) ?></p></div><div class="guided-review-signals"><?php foreach($reviewSignals as $signal):?><a href="<?= e($signal['href']) ?>" class="<?= $signal['ready']?'is-ready':'needs-attention' ?>"><i aria-hidden="true"><?= $signal['ready']?'✓':'!' ?></i><span><small><?= e($signal['label']) ?></small><b><?= e($signal['value']) ?></b></span></a><?php endforeach ?></div></section>
<div class="record-layout" data-section-workspace><main class="record-main"><nav class="record-tabs" data-section-tabs aria-label="Application record sections"><a href="#overview" class="active">Overview</a><a href="#academic">Academic</a><a href="#documents">Documents <b><?= count($documents) ?></b></a><a href="#payments">Payments <b><?= count($payments) ?></b></a><a href="#timeline">Timeline</a><a href="#snapshot-revisions">Revisions</a><a href="#notes">Notes <b><?= count($notes) ?></b></a></nav><section class="card record-section" id="overview"><div class="section-title"><div><span class="eyebrow">Candidate profile</span><h2>Personal information</h2></div></div><div class="data-grid"><div><span>Full name</span><b><?= e($fullName) ?></b></div><div><span>Date of birth</span><b><?= format_date($application['date_of_birth']) ?></b></div><div><span>Gender</span><b><?= e(ucfirst($application['gender']??'—')) ?></b></div><div><span>Category</span><b><?= e($application['category']??'—') ?></b></div><div><span>Nationality</span><b><?= e($application['nationality']??'—') ?></b></div><div><span>Government ID</span><b><?= e($application['government_id_last4']?'Restricted · ends '.$application['government_id_last4']:'Not collected') ?></b></div></div><h3 class="subsection-title">Address & guardian</h3><div class="data-grid"><div class="wide"><span>Permanent address</span><b><?= $address?e(implode(', ',array_filter([$address['address_line1'],$address['address_line2'],$address['city'],$address['district'],$address['state'],$address['postal_code']]))):'—' ?></b></div><div><span>Guardian</span><b><?= e($guardian['name']??'—') ?></b><small><?= e($guardian['relationship']??'') ?></small></div><div><span>Guardian contact</span><b><?= e($guardian['mobile']??'—') ?></b></div></div><h3 class="subsection-title">Programme preferences</h3><div class="preference-admin"><?php foreach($preferences as $pref):?><div><i><?= e($pref['preference_order']) ?></i><span><b><?= e($pref['name']) ?></b><small><?= e($pref['code']) ?></small></span><span class="status-pill status-<?= e($pref['allocation_status']) ?>"><?= e(ucfirst($pref['allocation_status'])) ?></span></div><?php endforeach?></div></section>
<section class="card record-section" id="academic"><div class="section-title"><div><span class="eyebrow">Qualification</span><h2>Academic history</h2></div><form method="post" action="<?= url('admin/applications/'.$application['id'].'/eligibility') ?>"><?= csrf_field() ?><button class="button button-outline button-sm">Run eligibility checks</button></form></div><div class="eligibility-review"><header><b>System assessment</b><span class="status-pill status-<?= e($application['eligibility_status']) ?>"><?= e(ucwords(str_replace('_',' ',$application['eligibility_status']))) ?></span></header><?php if($eligibilityFlags):?><?php foreach($eligibilityFlags as $result): $flags=$result['flags']??[$result]; if(isset($result['program_name'])):?><h3><?= e($result['program_name']) ?> <span class="status-pill status-<?= e($result['status']) ?>"><?= e(ucwords(str_replace('_',' ',$result['status']))) ?></span></h3><?php endif; foreach($flags as $flag):?><div><i class="<?= $flag['passed']?'pass':'fail' ?>"><?= $flag['passed']?'✓':'!' ?></i><span><b><?= e($flag['label']) ?></b><small>Actual: <?= e($flag['actual']) ?> · Expected: <?= e($flag['expected']) ?><?= $flag['blocking']?' · Blocking rule':'' ?></small></span></div><?php endforeach; endforeach?><?php else:?><p>Run the checks to compare every ranked programme against configured rules.</p><?php endif?><footer>Automated checks flag concerns; they do not replace the authorised officer’s final decision.</footer></div><div class="table-wrap"><table><thead><tr><th>Level</th><th>Board & institution</th><th>Year</th><th>Roll</th><th>Marks</th><th>Subjects</th></tr></thead><tbody><?php foreach($education as $record):?><tr><td><b><?= e(ucwords(str_replace('_',' ',$record['level']))) ?></b></td><td><?= e($record['board']) ?><small class="completion-small"><?= e($record['institution']) ?></small></td><td><?= e($record['passing_year']) ?></td><td><?= e($record['roll_number']) ?></td><td><b><?= e($record['percentage']) ?>%</b><small class="completion-small"><?= e($record['obtained_marks']) ?> / <?= e($record['total_marks']) ?></small></td><td><?= e($record['subjects']) ?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card record-section" id="documents"><div class="section-title"><div><span class="eyebrow">Verification desk</span><h2>Application documents</h2></div><span><?= count(array_filter($documents,fn($d)=>$d['status']==='verified')) ?>/<?= count($documents) ?> verified</span></div><div class="admin-doc-list"><?php foreach($documents as $doc):?><article><span class="doc-icon">▤</span><div><b><?= e($doc['document_name']) ?></b><small><?= e($doc['original_name']) ?> · revision <?= e($doc['revision_no']) ?> · <?= number_format($doc['size_bytes']/1024,0) ?> KB · SHA-256 recorded</small><?php if(count($doc['versions'])>1):?><details><summary><?= count($doc['versions']) ?> immutable revisions</summary><?php foreach($doc['versions'] as $version):?><a target="_blank" href="<?= url('files/document-version/'.$version['id']) ?>">Revision <?= e($version['revision_no']) ?> · <?= e($version['original_name']) ?> · <?= format_date($version['created_at'],true) ?></a><?php endforeach?></details><?php endif?><?php if($doc['review_remarks']):?><p><?= e($doc['review_remarks']) ?></p><?php endif?></div><span class="status-pill status-<?= e($doc['status']) ?>"><?= e(ucwords(str_replace('_',' ',$doc['status']))) ?></span><a target="_blank" href="<?= url('files/document/'.$doc['id']) ?>">View</a><?php if(can('documents.verify')):?><details><summary>Review</summary><form method="post" action="<?= url('admin/applications/'.$application['id'].'/documents/'.$doc['id']) ?>"><?= csrf_field() ?><select name="status"><option value="verified">Verify</option><option value="resubmission_required">Request resubmission</option><option value="rejected">Reject</option></select><input name="remarks" placeholder="Remarks when required"><button>Save</button></form></details><?php endif?></article><?php endforeach?><?php if(!$documents):?><div class="empty-inline">No documents uploaded.</div><?php endif?></div></section>
<section class="card record-section" id="payments"><div class="section-title"><div><span class="eyebrow">Accounts desk</span><h2>Payment records</h2></div></div><?php foreach($payments as $payment):?><article class="admin-payment"><div><span><?= e(strtoupper($payment['method'])) ?></span><b><?= money($payment['amount']) ?></b><small><?= e(ucwords(str_replace('_',' ',$payment['type']))) ?> · Ref: <?= e($payment['reference_number']) ?> · Paid <?= format_date($payment['paid_at']) ?></small><small>Assessment: <?= money($payment['base_amount']??$payment['amount']) ?> + <?= money($payment['late_fee_amount']??0) ?> late − <?= money($payment['discount_amount']??0) ?> discount · <?= e($payment['assessment_status']?:'legacy') ?></small><?php if($payment['receipt_number']):?><a target="_blank" href="<?= url('admin/payments/'.$payment['id'].'/receipt') ?>">Receipt <?= e($payment['receipt_number']) ?></a><?php endif?></div><span class="status-pill status-<?= e($payment['status']) ?>"><?= e(ucfirst($payment['status'])) ?></span><a href="<?= url('files/payment/'.$payment['id']) ?>" target="_blank">View proof</a><?php if(can('payments.verify')):?><form method="post" action="<?= url('admin/applications/'.$application['id'].'/payments/'.$payment['id']) ?>"><?= csrf_field() ?><select name="status"><option value="verified">Verify</option><option value="rejected">Reject</option></select><input name="remarks" placeholder="Verification note"><button class="button button-sm button-primary">Save</button></form><?php endif?></article><?php endforeach?><?php if(!$payments):?><div class="empty-inline">No payment proof submitted.</div><?php endif?></section>
<section class="card record-section" id="timeline"><div class="section-title"><div><span class="eyebrow">Audit-ready history</span><h2>Status timeline</h2></div></div><div class="timeline admin-timeline"><?php foreach($timeline as $event):?><article><i></i><div><span><?= e(ucwords(str_replace('_',' ',$event['to_status']))) ?></span><time><?= format_date($event['created_at'],true) ?></time><p><?= e($event['remarks']) ?></p><small><?= e($event['changed_by_name']?:'System') ?></small></div></article><?php endforeach?></div></section><section class="card record-section" id="snapshot-revisions"><div class="section-title"><div><span class="eyebrow">Immutable evidence</span><h2>Submission revisions</h2></div></div><div class="table-wrap"><table><thead><tr><th>Revision</th><th>Event</th><th>Configuration</th><th>Hash</th><th>Captured</th></tr></thead><tbody><?php foreach($snapshotRevisions as $revision):?><tr><td><b>#<?= e($revision['revision_no']) ?></b></td><td><?= e(ucwords(str_replace('_',' ',$revision['event_type']))) ?></td><td>v<?= e($revision['configuration_version']) ?></td><td><code><?= e(substr($revision['snapshot_hash'],0,18)) ?>…</code></td><td><?= format_date($revision['created_at'],true) ?><small class="completion-small"><?= e($revision['creator_name']?:'System') ?></small></td></tr><?php endforeach?></tbody></table></div><?php if(!$snapshotRevisions):?><div class="empty-inline">No submission snapshot has been captured.</div><?php endif?></section><section class="card record-section" id="notes"><div class="section-title"><div><span class="eyebrow">Staff only</span><h2>Internal notes</h2></div></div><?php foreach($notes as $note):?><div class="staff-note"><span><?= e(strtoupper(substr($note['author_name'],0,1))) ?></span><div><b><?= e($note['author_name']) ?></b><time><?= format_date($note['created_at'],true) ?></time><p><?= e($note['note']) ?></p></div></div><?php endforeach?><form method="post" action="<?= url('admin/applications/'.$application['id'].'/notes') ?>" class="note-form"><?= csrf_field() ?><textarea name="note" rows="3" placeholder="Add a private note for staff…" required></textarea><button class="button button-primary button-sm">Add note</button></form></section></main>
<aside class="record-aside"><section class="card decision-card" id="decision"><span class="eyebrow">Workflow action</span><h3>Update application status</h3><?php if($allocation):?><div class="report-notice"><span>◎</span><p><b><?= e($allocation['program_name']) ?></b><br><?= e($allocation['category'].' · '.$allocation['quota'].' · '.$allocation['status']) ?></p></div><?php endif?><?php if($allowedTransitions&&can('applications.decide')):?><form method="post" action="<?= url('admin/applications/'.$application['id'].'/status') ?>"><?= csrf_field() ?><input type="hidden" name="status_version" value="<?= e($application['status_version']) ?>"><label><span>New status</span><select name="status" required><?php foreach($allowedTransitions as $nextStatus): if($nextStatus==='correction_required')continue;?><option value="<?= e($nextStatus) ?>"><?= e(ucwords(str_replace('_',' ',$nextStatus))) ?></option><?php endforeach?></select></label><label><span>Programme for selection</span><select name="cycle_program_id"><option value="">Not applicable</option><?php foreach($cyclePrograms as $program):?><option value="<?= e($program['id']) ?>"<?= selected($application['selected_cycle_program_id'],$program['id']) ?>><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Seat category</span><select name="seat_category"><option value="">Applicant category</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"<?= selected($application['category'],$category['code']) ?>><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Seat quota</span><input name="seat_quota" value="<?= e($allocation['quota']??'state') ?>"></label><label><span>Decision / applicant remarks</span><textarea name="remarks" rows="4" placeholder="Required for rejection or withdrawal"></textarea></label><button class="button button-primary button-block">Save & notify applicant</button></form><?php else:?><p>No direct transition is available at the current stage.</p><?php endif?></section><?php if(can('applications.correct')&&in_array($application['status'],['submitted','resubmitted','eligibility_check','under_review'],true)):?><section class="card decision-card"><span class="eyebrow">Applicant action</span><h3>Request targeted corrections</h3><form method="post" action="<?= url('admin/applications/'.$application['id'].'/corrections') ?>"><?= csrf_field() ?><label><span>Reason</span><textarea name="reason" required></textarea></label><label><span>Deadline</span><input type="datetime-local" name="due_at"></label><label><span>Section</span><select name="target_key[]"><option value="">Select target</option><?php foreach($formSections as $section):?><option value="<?= e($section['section_key']) ?>"><?= e($section['title']) ?></option><?php endforeach?></select><input type="hidden" name="target_type[]" value="section"></label><label><span>Instructions</span><input name="target_instructions[]" placeholder="What must be corrected?"></label><label><span>Field (optional additional target)</span><select name="target_key[]"><option value="">None</option><?php foreach($formFields as $field):?><option value="<?= e($field['field_key']) ?>"><?= e($field['label']) ?></option><?php endforeach?></select><input type="hidden" name="target_type[]" value="field"></label><label><span>Field instructions</span><input name="target_instructions[]" placeholder="Correct this specific field"></label><label><span>Document (optional additional target)</span><select name="target_key[]"><option value="">None</option><?php foreach($documentRequirements as $requirement):?><option value="<?= e($requirement['code']) ?>"><?= e($requirement['name']) ?></option><?php endforeach?></select><input type="hidden" name="target_type[]" value="document"></label><label><span>Document instructions</span><input name="target_instructions[]" placeholder="Upload a clearer or corrected file"></label><button class="button button-outline button-block">Send correction request</button></form></section><?php endif?><?php if($corrections):?><section class="card"><h3>Correction history</h3><?php foreach($corrections as $correction):?><div class="staff-note"><div><b><?= e(ucfirst($correction['status'])) ?></b><time><?= format_date($correction['created_at'],true) ?></time><p><?= e($correction['reason']) ?></p><small><?= count($correction['items']) ?> targeted item(s)</small></div></div><?php endforeach?></section><?php endif?><section class="card assign-card"><h3>Assign reviewer</h3><form method="post" action="<?= url('admin/applications/'.$application['id'].'/assign') ?>"><?= csrf_field() ?><select name="assigned_to" required><option value="">Choose reviewer</option><?php foreach($reviewers as $reviewer):?><option value="<?= e($reviewer['id']) ?>"<?= selected($application['assigned_to'],$reviewer['id']) ?>><?= e($reviewer['name']) ?></option><?php endforeach?></select><button class="button button-outline button-block">Assign</button></form></section><section class="card compliance-mini"><span>⌾</span><h3>Protected record</h3><p>Views and decisions on this record are written to the audit trail. Status transitions and seat allocation are validated by server-side services.</p></section></aside></div>
